gIO(){return"\u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u0646\u06ce\u0646 \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645\u06ce / \u0648\u0627\u062a\u0633\u0627\u0628\u06ce"},
ga4y(){return"\u0626\u06d5\u0648 \u0646\u06d5\u062e\u06c6\u0634\u06ce\u0646 \u0628 \u0631\u06ce\u06a9\u0627 \u0628\u06c6\u062a\u06ce \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645\u06ce \u06cc\u0627\u0646 \u0648\u0627\u062a\u0633\u0627\u0628\u0627 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06ce \u062e\u06c6 \u062a\u06c6\u0645\u0627\u0631 \u06a9\u0631\u06cc\u0646. \u0648\u06d5\u06a9\u06cc \u0646\u06d5\u062e\u06c6\u0634\u06ce\u0646 \u0646\u0648\u0648 \u0632\u06ce\u062f\u06d5 \u0628\u06a9\u06d5\u060c \u06cc\u0627\u0646 \u0628 \u0641\u0627\u06cc\u0644\u06d5\u06a9\u0627 \u0647\u06d5\u06cc \u06a4\u06d5 \u06af\u0631\u06ce\u0628\u062f\u06d5\u060c \u06cc\u0627\u0646 \u0631\u06d5\u062a \u0628\u06a9\u06d5. \u062f \u0647\u06d5\u0631\u062f\u0648\u0648 \u062d\u0627\u0644\u06d5\u062a\u0627\u0646 \u062f\u0627 \u0646\u0627\u0645\u06d5\u06cc\u06d5\u06a9 \u062f\u06ce \u0628\u06c6 \u0648\u0627\u0646 \u0686\u06cc\u062a."},
ga4x(){return"\u0686 \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u0646 \u0686\u0627\u06a4\u06d5\u0695\u06ce \u0646\u06cc\u0646\u0646."},
t6(a){return"\u0646\u06d5\u0647\u0627\u062a\u06d5 \u067e\u0627\u0634\u06d5\u06a9\u06d5\u0641\u062a\u06a9\u0631\u0646: "+a},
